import { KANA_ITEMS } from './kana';
import {
  ITEM_TYPES,
  LEVELS,
  type GrammarItem,
  type Item,
  type ItemType,
  type KanjiItem,
  type Level,
  type Skill,
  type TrapItem,
  type VocabItem,
} from './types';

// Generated by `npm run build:content` from the sources in /content.
// `require` keeps TypeScript from inferring literal types for thousands of entries.
export const VOCAB_ITEMS = require('./data/vocab.json') as readonly VocabItem[];
export const KANJI_ITEMS = require('./data/kanji.json') as readonly KanjiItem[];
export const GRAMMAR_ITEMS = require('./data/grammar.json') as readonly GrammarItem[];
export const TRAP_ITEMS = require('./data/traps.json') as readonly TrapItem[];

export { KANA_ITEMS };

export const ALL_ITEMS: readonly Item[] = [
  ...KANA_ITEMS,
  ...VOCAB_ITEMS,
  ...KANJI_ITEMS,
  ...GRAMMAR_ITEMS,
  ...TRAP_ITEMS,
];

const byId = new Map<string, Item>(ALL_ITEMS.map((item) => [item.id, item]));

export function getItem(id: string): Item | undefined {
  return byId.get(id);
}

const byDifficulty = (a: Item, b: Item) => a.d - b.d;

/** Items of each type, easiest first. */
export const ITEMS_BY_TYPE: Record<ItemType, readonly Item[]> = {
  kana: [...KANA_ITEMS].sort(byDifficulty),
  vocab: [...VOCAB_ITEMS].sort(byDifficulty),
  kanji: [...KANJI_ITEMS].sort(byDifficulty),
  grammar: [...GRAMMAR_ITEMS].sort(byDifficulty),
  trap: [...TRAP_ITEMS].sort(byDifficulty),
};

export function skillOf(type: ItemType): Skill {
  return type === 'trap' ? 'vocab' : type;
}

const PREFIX: Record<string, ItemType> = { ka: 'kana', v: 'vocab', k: 'kanji', g: 'grammar', t: 'trap' };

/** Item type from the id prefix; works even for ids no longer present in the content. */
export function typeOfId(id: string): ItemType | undefined {
  return PREFIX[id.slice(0, id.indexOf(':'))];
}

/** Number of items per level and type. */
export const ITEM_COUNTS: Record<Level, Record<ItemType, number>> = (() => {
  const counts = Object.fromEntries(
    LEVELS.map((level) => [level, Object.fromEntries(ITEM_TYPES.map((t) => [t, 0]))]),
  ) as Record<Level, Record<ItemType, number>>;
  for (const item of ALL_ITEMS) counts[item.level][item.type] += 1;
  return counts;
})();
